-- ncm-core module: world.speed_limits
-- Advertised speed limits for Racing Week (owner, 2026-10-03, L301): the game's own posted lane speeds, modulated
-- by the Day, and what going over them costs.
--
-- POSTED. Every vehicle lane the game cooks carries `maxSpeed` (10 / 15 / 17 m/s; 36 / 54 / 61 km/h). The server
-- index (`ncm_world/server/lane_limits_data.lua`, generated by tools/gen-lane-limits.py) is built into 32 m cells
-- here, once, with a yield so OPEN//77's per-handler metering is never hit (KB-211).
--
-- ADVERTISED = posted x the organisers' current factor, signed to the nearest 5 km/h. The factor, the race rule and
-- police posture come from `week.curve` (L302): announced steps (x0.75 "keep it friendly" -> x1.6 "we hear you" ->
-- x1.0 "standard traffic law" -> x0.8 "clear the roads"), fired by the run's tolerance, not by the clock's Day.
-- Police are proportional everywhere: the rolling minute of excess sets an NCPD wanted level; the curve sets the bar
-- (`perLevel`) and the ceiling (`cap`) from the city's tolerance.
--
-- EXCESS is metre-seconds over (advertised + grace): 10 km/h over for a minute is ~167, 30 km/h over ~500.
-- Pure and deterministic; the host passes time and speed in.
local Core = NcmCore

Core.define("world.speed_limits", function(C)
    local M = { version = "0.1.0", CELL = 32, KPH = 3.6 }
    local floor, sqrt, abs = math.floor, math.sqrt, math.abs
    local function atan2(y, x)
        if math.atan2 then return math.atan2(y, x) end      -- LuaJIT
        return math.atan(y, x)
    end

    M.POLICY = {
        graceKph = 5,           -- over the sign by less than this is not over
        windowS = 60,           -- the rolling window the wanted level reads
        perLevel = 150,         -- excess metre-seconds in the window per wanted level (the curve overrides it)
        penaltyPer = 150,       -- Day-1 race penalty: 1 s per this many excess metre-seconds ...
        penaltyStepS = 5,       -- ... issued in steps of this many seconds (one toast per step, not per second)
        penaltyCapS = 30,       -- and never more than this in one race
        laneRadius = 12,        -- metres: further than this from any lane is off-road (no sign)
        keepRadius = 8,         -- hysteresis: the current lane is kept while within this
        maxDz = 4,              -- an overpass above or below is a different road
    }

    -- ------------------------------------------------------------------------------------------------ the index

    -- an integer key per 32 m cell (no per-cell string key)
    local function cellId(cx, cy) return (cx + 100000) * 200000 + (cy + 100000) end
    local function cellKey(x, y) return cellId(floor(x / M.CELL), floor(y / M.CELL)) end

    --- Build the lookup from the generated data (`{ [mps] = "x,y,z;x,y,z|..." }`). `yield` is called now and then.
    --- COMPACT (KB-327): a lane keeps its encoded string, not a table of points -- the decoded index cost 12 MB and
    --- pushed ncm_world over its 64 MB Lua quota. Points are decoded on demand (`points`), through a small cache.
    local function decode(text)
        local pts = {}
        for x, y, z in text:gmatch("(-?%d+),(-?%d+),(-?%d+)") do
            pts[#pts + 1] = tonumber(x); pts[#pts + 1] = tonumber(y); pts[#pts + 1] = tonumber(z)
        end
        return pts
    end

    function M.build(data, yield)
        -- flat: lane speeds and encoded texts in two arrays; a cell is a comma-joined string of lane ids
        local idx = { mps = {}, text = {}, cells = {}, points = 0, cache = {}, cacheOrder = {}, CACHE = 96, count = 0 }
        local building = {}
        local n = 0
        local speeds = {}
        for mps in pairs(data or {}) do speeds[#speeds + 1] = mps end
        table.sort(speeds)
        for _, mps in ipairs(speeds) do
            for laneText in data[mps]:gmatch("[^|]+") do
                local pts = decode(laneText)
                local np = #pts / 3
                if np >= 2 then
                    local id = idx.count + 1
                    idx.count = id
                    idx.mps[id], idx.text[id] = mps, laneText
                    idx.points = idx.points + np
                    -- every cell a segment touches, sampled every half cell
                    for i = 0, np - 2 do
                        local ax, ay, bx, by = pts[i * 3 + 1], pts[i * 3 + 2], pts[i * 3 + 4], pts[i * 3 + 5]
                        local len = sqrt((bx - ax) ^ 2 + (by - ay) ^ 2)
                        local steps = math.max(1, math.ceil(len / (M.CELL / 2)))
                        for st = 0, steps do
                            local k = cellKey(ax + (bx - ax) * st / steps, ay + (by - ay) * st / steps)
                            local list = building[k]
                            if not list then list = {}; building[k] = list end
                            if list[#list] ~= id then list[#list + 1] = id end
                        end
                    end
                end
                n = n + 1
                if yield and n % 200 == 0 then yield() end
            end
        end
        for k, list in pairs(building) do idx.cells[k] = table.concat(list, ",") end
        building = nil
        return idx
    end

    --- A lane's points, decoded on demand and kept in a small most-recently-used cache.
    function M.points(idx, id)
        local hit = idx.cache[id]
        if hit then return hit end
        local text = idx.text[id]
        if not text then return nil end
        local pts = decode(text)
        idx.cache[id] = pts
        idx.cacheOrder[#idx.cacheOrder + 1] = id
        if #idx.cacheOrder > idx.CACHE then idx.cache[table.remove(idx.cacheOrder, 1)] = nil end
        return pts
    end

    -- Distance from (x, y, z) to one lane, and that segment's undirected heading difference to `heading` (degrees).
    local function laneDistance(p, x, y, z, heading, maxDz)
        local best, bestAng = math.huge, 0
        for i = 0, #p / 3 - 2 do
            local ax, ay, az, bx, by, bz = p[i * 3 + 1], p[i * 3 + 2], p[i * 3 + 3], p[i * 3 + 4], p[i * 3 + 5], p[i * 3 + 6]
            local dx, dy = bx - ax, by - ay
            local l2 = dx * dx + dy * dy
            local t = l2 > 0 and math.max(0, math.min(1, ((x - ax) * dx + (y - ay) * dy) / l2)) or 0
            local qx, qy, qz = ax + dx * t, ay + dy * t, az + (bz - az) * t
            if abs(z - qz) <= maxDz then
                local d = sqrt((x - qx) ^ 2 + (y - qy) ^ 2)
                if d < best then
                    best = d
                    if heading and l2 > 0 then
                        local segH = math.deg(atan2(dy, dx))
                        local diff = abs((heading - segH + 180) % 360 - 180)
                        bestAng = diff > 90 and 180 - diff or diff     -- undirected: a two-way road is one limit
                    end
                end
            end
        end
        return best, bestAng
    end

    --- The lane under a car. Returns laneId, postedMps, distance -- or nil when off-road.
    --- `heading` (degrees, atan2(dy, dx) convention) prefers the aligned road at junctions; `prev` is kept while near.
    function M.nearest(idx, x, y, z, heading, prev, policy)
        policy = policy or M.POLICY
        if not idx or not x then return nil end
        z = z or 0
        if prev and idx.text[prev] then
            local d, ang = laneDistance(M.points(idx, prev), x, y, z, heading, policy.maxDz)
            if d <= policy.keepRadius and ang <= 60 then return prev, idx.mps[prev], d end
        end
        local cx, cy = floor(x / M.CELL), floor(y / M.CELL)
        local bestId, bestScore, bestD = nil, math.huge, nil
        local seen = {}
        for ix = cx - 1, cx + 1 do
            for iy = cy - 1, cy + 1 do
                for sid in (idx.cells[cellId(ix, iy)] or ""):gmatch("%d+") do
                    local id = tonumber(sid)
                    if not seen[id] then
                        seen[id] = true
                        local d, ang = laneDistance(M.points(idx, id), x, y, z, heading, policy.maxDz)
                        if d <= policy.laneRadius then
                            local score = d + (ang > 60 and 20 or ang / 15)       -- a crossing road loses to ours
                            if score < bestScore then bestId, bestScore, bestD = id, score, d end
                        end
                    end
                end
            end
        end
        if not bestId then return nil end
        return bestId, idx.mps[bestId], bestD
    end

    -- ------------------------------------------------------------------------------------------------ the sign

    --- The advertised limit for a posted speed under the organisers' factor. Returns mps, kph (the sign, a multiple of 5).
    function M.advertised(postedMps, factor)
        local kph = floor((postedMps * M.KPH * (tonumber(factor) or 1)) / 5 + 0.5) * 5
        if kph < 5 then kph = 5 end
        return kph / M.KPH, kph
    end

    -- ------------------------------------------------------------------------------------------------ accounting

    function M.newState() return { samples = {}, excess60 = 0, raceExcess = 0, penaltyS = 0, maxOverKph = 0 } end

    --- One sample. `speedMps` the car's speed, `advMps` the sign (nil = off-road: nothing accrues), `dt` seconds since
    --- the previous sample (clamped to 2 s: a gap is not evidence), `t` seconds. Returns the over-speed in km/h now.
    function M.account(st, speedMps, advMps, dt, t, policy)
        policy = policy or M.POLICY
        dt = math.max(0, math.min(2, dt or 0))
        local overMps = 0
        if advMps then overMps = math.max(0, (speedMps or 0) - advMps - policy.graceKph / M.KPH) end
        local e = overMps * dt
        st.samples[#st.samples + 1] = { t = t, e = e }
        st.excess60 = st.excess60 + e
        while #st.samples > 0 and st.samples[1].t <= t - policy.windowS do
            st.excess60 = st.excess60 - table.remove(st.samples, 1).e
        end
        if st.excess60 < 1e-9 then st.excess60 = 0 end
        if st.inRace then st.raceExcess = st.raceExcess + e end
        local overKph = overMps > 0 and (overMps * M.KPH + policy.graceKph) or 0
        if overKph > st.maxOverKph then st.maxOverKph = overKph end
        return overKph
    end

    --- The wanted level the last minute earns, under the curve's ceiling and bar.
    function M.wanted(excess60, cap, perLevel)
        local lvl = math.ceil((excess60 or 0) / (tonumber(perLevel) or M.POLICY.perLevel) - 1e-9)
        return math.max(0, math.min(tonumber(cap) or 5, lvl))
    end

    --- Start or end a race window. Race totals reset at the start.
    function M.raceStart(st) st.inRace, st.raceExcess, st.penaltyS, st.warned = true, 0, 0, 0 end
    function M.raceEnd(st) st.inRace = false end

    --- What the race owes now under the organisers' rule `race` ("penalty" | "warning" | "police"):
    --- { penaltyS = seconds newly due }, { warning = n }, or nil. Steps keep the toasts sparse; a cap bounds the race.
    function M.raceDue(st, race, policy)
        policy = policy or M.POLICY
        if not st.inRace then return nil end
        if race == "penalty" then
            local earned = floor(st.raceExcess / policy.penaltyPer / policy.penaltyStepS) * policy.penaltyStepS
            earned = math.min(policy.penaltyCapS, earned)
            if earned > st.penaltyS then
                local due = earned - st.penaltyS
                st.penaltyS = earned
                return { penaltyS = due, totalS = earned }
            end
        elseif race == "warning" then
            local n = floor(st.raceExcess / (policy.penaltyPer * policy.penaltyStepS))
            if n > (st.warned or 0) then st.warned = n; return { warning = n } end
        end
        return nil
    end

    return M
end)
